// Agente de Desenvolvimento - Inicialização
// Especialista em: Frontend (React/Vite), Backend (FastAPI), Código, Integração

const payload = $input.item.json.body || $input.item.json;

return [{
  json: {
    agent: {
      name: 'Agente de Desenvolvimento',
      version: '1.0',
      specialization: ['React', 'TypeScript', 'FastAPI', 'Python', 'Frontend', 'Backend', 'API'],
      role: 'Diagnóstico e resolução de problemas de código e desenvolvimento'
    },
    sessionId: payload.sessionId,
    timestamp: payload.timestamp,
    issues: payload.issues || [],
    context: payload.context || {},
    orchestratorDecision: payload.orchestratorDecision || {},
    status: 'analyzing'
  }
}];

// Agregar dados coletados para análise
const agentData = $('Inicializar Agente').item.json;
const apiDocs = $('Verificar API Docs').item.json;
const frontend = $('Verificar Frontend').item.json;
const apiHealth = $('Verificar Erros API').item.json;

const collectedData = {
  apiDocs: {
    available: apiDocs.statusCode === 200,
    status: apiDocs.statusCode
  },
  frontend: {
    status: frontend.statusCode,
    healthy: frontend.statusCode === 200,
    content: typeof frontend.body === 'string' ? frontend.body.substring(0, 500) : ''
  },
  api: {
    status: apiHealth.statusCode,
    response: apiHealth.body || {},
    hasErrors: apiHealth.statusCode >= 400
  }
};

return [{
  json: {
    ...agentData,
    collectedData: collectedData,
    readyForAnalysis: true
  }
}];

// Preparar prompt para Claude AI
const data = $input.item.json;
const promptTemplate = $env.PROMPT_DEV_SPECIALIST || '';

// Substituir placeholders no prompt
let prompt = promptTemplate
  .replace(/\{\{issues\}\}/g, JSON.stringify(data.issues, null, 2))
  .replace(/\{\{context\}\}/g, JSON.stringify({
    ...data.context,
    collectedData: data.collectedData
  }, null, 2));

// Adicionar contexto do agente
prompt = `Você é o Agente de Desenvolvimento do CredGestor.\n\n` + prompt;

return [{
  json: {
    ...data,
    prompt: prompt,
    model: $env.LLM_MODEL || 'claude-3-5-sonnet-20241022'
  }
}];

